export function disneyPlaceLink(parkId, placeId) {
  const path = details[placeId];
  return {
    url: 'https://disneyworld.disney.go.com' + (path ?? '/destinations/' + parkId + '/'),
    label: path ? 'View on Disney' : 'View park on Disney'
  };
}
